const P=(it,en)=>({it,en});
const img=(name,it,en)=>({name,cap:P(it,en)});
const sheet=(name,it,en,kind='detail')=>({name,cap:P(it,en),kind});
const chapter=(image,it,en,textIt,textEn,capIt,capEn)=>({image:img(image,capIt,capEn),title:P(it,en),body:P(textIt,textEn)});

/* Each image name appears exactly once across the whole site (checked by check.mjs). */
const projects=[
{id:'monoblock',name:'MONOBLOCK',featured:true,discipline:'exhibition',
 type:P('Tesi · Exhibition design','Thesis · Exhibition design'),year:'2026',
 cover:img('mb-fauteuil','Postazione Fauteuil 300','The Fauteuil 300 station'),
 subtitle:P('Il progetto si ferma al cancello della fabbrica.','Design stops at the factory gate.'),
 question:P('Che cosa succede quando il prodotto ha finito di servirci?','What happens when a product is no longer useful to us?'),
 lens:P('La mia ricerca parte da una sedia ordinaria per allargare il campo del progetto: dall’oggetto alle condizioni che ne determinano il destino.','My research starts with an ordinary chair and broadens the scope of design: from the object to the conditions that determine its future.'),
 intro:P('Una sedia comune diventa il punto di partenza per interrogare il ciclo di vita degli oggetti. MONOBLOCK mette in scena la distanza tra una produzione ottimizzata e un fine vita ancora da progettare.','An everyday chair becomes the starting point for questioning the life cycle of objects. MONOBLOCK stages the gap between optimised production and an end of life that still needs to be designed.'),
 text:P('L’allestimento collega storia, materia e responsabilità. Griglia, pannelli e tende costruiscono il percorso; un’installazione di sei stampanti 3D produce oggetti che diventano subito scarto. L’accumulo rende visibile ciò che la produzione lascia dopo di sé.','The exhibition connects history, matter and responsibility. A grid, panels and curtains shape the route; an installation of six 3D printers produces objects that immediately become waste. Accumulation makes visible what production leaves behind.'),
 meta:[[P('Contesto','Context'),P('Tesi di laurea · Design degli Interni','Bachelor’s thesis · Interior Design')],[P('Sede','School'),P('Politecnico di Milano · A.A. 2025/26','Politecnico di Milano · A.Y. 2025/26')],[P('Relatore','Supervisor'),P('Marcello Galbiati','Marcello Galbiati')]],
 team:'Filippo Antonio Visentin',
 chapters:[
  chapter('mb-sedia4999','Una sedia, una contraddizione','One chair, one contradiction','La tesi usa il Monobloc come protagonista di una domanda sul design industriale. La semplicità del prodotto e l’efficienza del processo non risolvono da sole la gestione dopo l’uso. Il percorso intreccia la storia delle sedie in plastica, le tecniche produttive e il problema del fine vita. Le sedie storiche sono oggetti della ricerca, non prodotti disegnati per questo progetto.','The thesis uses the Monobloc to question industrial design. Simplicity and production efficiency do not, by themselves, resolve what happens after use. The exhibition connects the history of plastic chairs, manufacturing techniques and end-of-life issues. Historical chairs are subjects of research, not products designed for this project.','Postazione Sedia 4999','The Sedia 4999 station'),
  chapter('mb-percorso','Lo spazio come argomento','Space as an argument','Una griglia modulare di alluminio, pannelli e tende semitrasparenti organizzano la mostra. I moduli quadrati di 50 × 50 cm costruiscono un’infrastruttura di sospensione, mentre i tessuti definiscono soglie senza isolare completamente le aree. La possibilità di separare alluminio, acciaio e tessuto fa parte del tema: l’allestimento deve interrogarsi anche sul proprio smontaggio.','A modular aluminium grid, panels and translucent curtains organise the exhibition. Square 50 × 50 cm modules create a suspension infrastructure, while fabric defines thresholds without fully isolating each area. Separating aluminium, steel and fabric is part of the argument: the exhibition must also consider its own disassembly.','Pareti curve e tende lungo il percorso','Curved walls and curtains along the route'),
  chapter('mb-collezione','Produrre, lasciare, ricominciare','Produce, leave, repeat','Sei stampanti 3D inclinate producono oggetti che, una volta completati, scivolano a terra. La macchina riparte e nessuno raccoglie il risultato: l’accumulo rende visibile il tempo della mostra. L’installazione mette in discussione una produzione che sa controllare ogni fase fino all’uscita dell’oggetto, ma non ciò che avviene dopo.','Six tilted 3D printers produce objects that slide onto the floor when complete. The machine starts again and nobody collects the result: accumulation makes the exhibition’s duration visible. The installation questions production that controls every stage until the object leaves the machine, but not what happens afterwards.','L’accumulo della materia','The accumulation of matter')],
 gallery:[img('mb-endless','Postazione Endless Chair','The Endless Chair station'),img('mb-selene','Postazione Selene','The Selene station'),img('mb-manifesto','La parete manifesto','The manifesto wall'),img('mb-binario','Dettaglio — pannello e binario','Detail — panel and rail'),img('mb-connessione','Dettaglio — connessione filettata','Detail — threaded connection')],
 technical:[sheet('mb-tav-30','Planimetria — parte I','Floor plan — part I','plan'),sheet('mb-tav-31','Planimetria — parte II','Floor plan — part II','plan'),...[32,33,34,35].map(n=>sheet('mb-tav-'+n,'Disposizione e collezione — '+(n-31),'Layout and collection — '+(n-31),'plan')),sheet('mb-tav-36','Griglia e sistema di sospensione','Grid and suspension system'),sheet('mb-tav-37','Connessioni meccaniche','Mechanical connections'),sheet('mb-tav-38','Tende e partizioni','Curtains and partitions'),sheet('mb-tav-39','Installazione delle stampanti 3D','3D printer installation'),sheet('mb-tav-40','Progetto della luce','Lighting design'),sheet('mb-tav-41','Apparecchi illuminanti','Lighting fixtures'),sheet('mb-tav-42','Materiali — abaco I','Materials — schedule I'),sheet('mb-tav-43','Materiali — abaco II','Materials — schedule II'),sheet('mb-tav-44','Identità e tipografia','Identity and typography','board'),sheet('mb-tav-45','Il colore nel tempo','Colour over time','board')]},

{id:'bivacuum',name:'BIVACUUM',featured:true,discipline:'architecture',
 type:P('Architettura · Spazio minimo','Architecture · Minimum space'),year:'',
 cover:img('bv-cover','Il rifugio nel paesaggio alpino','The shelter in the alpine landscape'),
 subtitle:P('Abitare la quota. Liberare lo spazio.','Living at altitude. Freeing up space.'),
 question:P('Come può uno spazio minimo accogliere modi diversi di stare insieme?','How can a minimum space accommodate different ways of being together?'),
 lens:P('La montagna incontra il mio interesse per i sistemi trasformabili: partire dai gesti di chi arriva, si riposa e riparte.','The mountains meet my interest in transformable systems: beginning with the gestures of arriving, resting and setting off again.'),
 intro:P('Un rifugio per almeno otto persone, pensato per la Grignetta. Una struttura trasportabile e preassemblata accoglie un interno capace di cambiare tra il riposo e la vita condivisa.','A shelter for at least eight people, conceived for the Grignetta. A transportable, preassembled structure contains an interior that shifts between rest and shared life.'),
 text:P('Il soffitto diventa infrastruttura: i binari permettono di sospendere le amache e riconfigurare l’ambiente. Tavoli ripiegabili e sedute integrate liberano il pavimento. Involucro, fondazioni a vite e pannelli fotovoltaici orientabili sono parti di un unico sistema.','The ceiling becomes infrastructure: rails support hammocks and allow the room to be reconfigured. Folding tables and integrated seating free up the floor. The envelope, screw foundations and adjustable solar panels are parts of a single system.'),
 meta:[[P('Luogo','Site'),P('Grignetta · bivacco alpino','Grignetta · alpine shelter')],[P('Sistema','System'),P('Modulare · giorno / notte','Modular · day / night')],[P('Capienza','Capacity'),P('Almeno 8 persone','At least 8 people')]],
 team:'Filippo Antonio Visentin, Anton Qerkini',
 chapters:[
  chapter('bv-crepuscolo','Arrivare e trovare riparo','Arriving and finding shelter','Il brief prevede almeno otto posti, uso nelle diverse stagioni e una struttura preassemblata con montaggio ridotto sul posto. Il contesto è un terrazzo naturale sul percorso verso la Grignetta, pensato come punto di riparo e sosta. La compattezza risponde sia all’abitare sia al trasporto e all’installazione.','The brief calls for at least eight places, use across seasons and a preassembled structure requiring limited on-site work. The setting is a natural terrace on the way to the Grignetta, conceived as a place for shelter and rest. Compactness addresses living, transport and installation.','Al crepuscolo, in quota','At dusk, at altitude'),
  chapter('bv-schizzo-amache','Il soffitto libera il pavimento','The ceiling frees the floor','Una rete di binari permette di appendere e spostare le amache. Di giorno l’interno diventa uno spazio comune; di notte le superfici sospese accolgono il riposo. Tavoli a parete ripiegabili e sedute integrate riducono gli ingombri fissi: la trasformazione nasce da operazioni semplici, leggibili negli schizzi e nelle sezioni.','A network of rails allows hammocks to be suspended and moved. During the day the interior becomes shared space; at night suspended surfaces provide rest. Folding wall tables and integrated seating reduce fixed obstructions: transformation comes from simple operations, described in sketches and sections.','Schizzo — le amache sospese','Sketch — suspended hammocks'),
  chapter('bv-gancio','Pensare per strati e connessioni','Thinking through layers and connections','L’involucro studiato nel progetto combina compensato interno, struttura lignea, vuoto tecnico, barriera al vapore, isolamento in lana di pecora, camera ventilata e rivestimento metallico. Le tavole approfondiscono anche le fondazioni a vite e il sistema fotovoltaico a inclinazione regolabile. Sono soluzioni di progetto da leggere insieme, alla scala del dettaglio e dell’insieme.','The proposed envelope combines internal plywood, a timber structure, a service cavity, vapour barrier, sheep-wool insulation, a ventilated cavity and metal cladding. The drawings also study screw foundations and adjustable photovoltaic panels. These design proposals are best read together, at both detail and overall scales.','Il gancio scorre nel binario','The hook slides along the rail')],
 compare:{before:img('bv-sezione-giorno','Sezione — configurazione giorno','Section — day configuration'),after:img('bv-sezione-notte','Sezione — configurazione notte','Section — night configuration')},
 gallery:[img('bv-interno-giorno','Interno — giorno','Interior — day'),img('bv-interno-notte','Interno — notte','Interior — night'),img('bv-finestra','L’oblò sulla valle','The porthole over the valley'),img('bv-lucernario','Il lucernario e il soffitto attrezzato','The skylight and the equipped ceiling'),img('bv-schizzo-griglia','Schizzo — la griglia strutturale','Sketch — the structural grid'),img('bv-schizzo-tavoli','Schizzo — i tavoli ripiegabili','Sketch — folding tables')],
 technical:[sheet('bv-copertura','Pianta della copertura','Roof plan','plan'),sheet('bv-sezione-trasversale','Sezione trasversale','Cross section','section'),sheet('bv-prospetto','Prospetto ovest','West elevation','section'),sheet('bv-stratigrafia','Stratigrafia dell’involucro','Envelope layers'),sheet('bv-fondazione','Fondazioni a vite','Screw foundations'),sheet('bv-fotovoltaico','Fotovoltaico orientabile','Adjustable photovoltaics')]},

{id:'oltreetrusco',name:'OLTRE ETRUSCO',featured:true,discipline:'exhibition',
 type:P('Exhibition design · Cultura','Exhibition design · Culture'),year:'2025',
 cover:img('ot-cover','Sala 3 — esplorazione libera','Room 3 — free exploration'),
 subtitle:P('Attraversare un confine. Poi un altro.','Crossing a boundary. Then another.'),
 question:P('Può un allestimento cambiare il nostro modo di attraversare una storia?','Can an exhibition change how we move through a story?'),
 lens:P('Mi interessa il confine quando diventa una possibilità: orientare il visitatore e poi lasciargli libertà.','I am interested in boundaries as possibilities: guiding visitors, then giving them freedom.'),
 intro:P('Un percorso espositivo che interpreta lo sconfinamento tra passato e presente. Da una sequenza guidata a uno spazio libero, i limiti si dissolvono progressivamente e cambiano il modo di incontrare i reperti.','An exhibition journey exploring boundaries between past and present. From a guided sequence to an open space, boundaries gradually dissolve and change the way visitors encounter the artefacts.'),
 text:P('Il sistema Oltre usa strutture metalliche modulari e supporti regolabili. La progressione delle sale accompagna il visitatore da un percorso obbligato a una scoperta più autonoma, fino a soglie leggere e tende.','The Oltre system uses modular metal structures and adjustable supports. The progression of rooms guides visitors from a prescribed route towards independent discovery, ending with light thresholds and curtains.'),
 meta:[[P('Sede','School'),P('Politecnico di Milano · A.A. 2024/25','Politecnico di Milano · A.Y. 2024/25')],[P('Tema','Brief'),P('Allestimento museale','Museum exhibition')],[P('Sistema','System'),P('Sistema espositivo Oltre','Oltre display system')]],
 team:'Filippo Antonio Visentin, Anton Qerkini, Noè Bartolini, Jacopo Dellanoce, Luca Mastromatteo',
 chapters:[
  chapter('ot-schizzo-1','Lo sconfinamento come regola','Crossing boundaries as a principle','Oltre Etrusco mette in relazione passato e presente attraverso il tema dello sconfinamento. Il percorso non è una sequenza neutra di oggetti: cambia il grado di libertà del visitatore. Nella prima sala il limite indica dove passare; nelle successive la struttura si apre e la lettura diventa più personale.','Oltre Etrusco connects past and present through the crossing of boundaries. The route is not a neutral sequence of objects: it changes the visitor’s degree of freedom. In the first room boundaries define the route; later the structure opens up and interpretation becomes more personal.','Schizzo — il percorso guidato','Sketch — the guided route'),
  chapter('ot-sala3','Dal percorso alla scoperta','From a route to discovery','La seconda sala interrompe progressivamente i confini e la terza distribuisce gli elementi nello spazio. La sala dedicata alla Tomba degli Auguri introduce un altro momento del racconto; le sale finali e il corridoio lavorano con soglie più leggere e tende. Le piante permettono di seguire questa progressione stanza per stanza.','The second room progressively interrupts boundaries; the third distributes elements throughout the space. The room dedicated to the Tomb of the Augurs introduces another chapter, while final rooms and the corridor use lighter thresholds and curtains. The plans reveal this progression room by room.','Sala 3 — la prospettiva lunga','Room 3 — the long perspective'),
  chapter('ot-struttura','Una struttura che si adatta','An adaptable structure','Oltre è un sistema di strutture metalliche modulari con supporti regolabili. L’esploso descrive come le parti costruiscono l’insieme; i dettagli mostrano il passaggio dalla regola spaziale al dispositivo che sostiene e presenta i reperti. La flessibilità del sistema rende possibili configurazioni differenti lungo il percorso.','Oltre is a system of modular metal structures with adjustable supports. The exploded drawing describes how the parts form the whole; details connect the spatial principle to the device supporting and displaying artefacts. System flexibility enables different configurations along the route.','Sistema Oltre — esploso del supporto','Oltre system — exploded support')],
 gallery:[img('ot-sala2','Sala 2 — confini permeabili','Room 2 — permeable boundaries'),img('ot-sala4-a','Sala 4 — il limite','Room 4 — the boundary'),img('ot-sala4-b','Sala 4 — attraversamento','Room 4 — crossing'),img('ot-schizzo-2','Schizzo — lo spazio aperto','Sketch — the open space'),img('ot-sequenza','La sequenza delle sale','The sequence of rooms')],
 technical:[sheet('ot-tav-sala1','Sala 1 — percorso guidato','Room 1 — guided route','plan'),sheet('ot-tav-sala2','Sala 2 — confine permeabile','Room 2 — permeable boundary','plan'),sheet('ot-tav-sala3a','Sala 3 — studio I','Room 3 — study I','plan'),sheet('ot-tav-sala3b','Sala 3 — studio II','Room 3 — study II','plan'),sheet('ot-tav-corridoio','Sale finali e corridoio','Final rooms and corridor','plan'),sheet('ot-sezioni','Sezioni delle sale','Room sections','section'),sheet('ot-tav-esploso','Esploso dell’allestimento','Exhibition exploded view','board'),sheet('ot-tav-dettagli','Dettagli del sistema Oltre','Oltre system details')]},

{id:'poliedro',name:'POLIEDRO',featured:true,discipline:'product',
 type:P('Product design · Arredo urbano','Product design · Urban furniture'),year:'2026',
 cover:img('pl-cover','Un’isola sociale al tramonto','A social island at sunset'),
 subtitle:P('Una geometria. Molti modi di stare insieme.','One geometry. Many ways of being together.'),
 question:P('Come dare forma a un incontro senza decidere come debba avvenire?','How can we shape an encounter without deciding how it should happen?'),
 lens:P('Parto dalle persone e dalle distanze tra loro. Il modulo è uno strumento per lasciare spazio a relazioni diverse.','I start with people and the distances between them. A module is a tool for making room for different relationships.'),
 intro:P('Un sistema di sedute modulari in calcestruzzo che costruisce luoghi di relazione. La matrice esagonale permette aggregazioni aperte, mentre una lampada trasforma il centro della composizione in un punto d’incontro.','A system of modular concrete seats that creates places for connection. A hexagonal matrix allows open-ended arrangements, while a lamp turns the centre of the composition into a meeting point.'),
 text:P('Altezze, cavità e appoggi differenziano l’uso mantenendo una famiglia formale comune. La luce introduce un secondo tempo di vita dello spazio pubblico. L’allestimento A matter of presence sviluppa il racconto spaziale di questa ricerca.','Heights, cavities and supports create different uses within a shared formal family. Light introduces a second rhythm to public space. The exhibition A matter of presence develops the spatial narrative of this research.'),
 meta:[[P('Corso','Studio'),P('Laboratorio di sintesi finale · A.A. 2025/26','Final design studio · A.Y. 2025/26')],[P('Sistema','System'),P('Sedute modulari e illuminazione','Modular seating and lighting')],[P('Materiali','Materials'),P('Calcestruzzo · policarbonato','Concrete · polycarbonate')]],
 team:'Filippo Antonio Visentin, Lawrence Sedra, Anna Varsavia, Nina Rosa Patanè',related:'presence',
 chapters:[
  chapter('pl-notte','Piccole isole sociali','Small social islands','POLIEDRO nasce per favorire l’interazione tra giovani nello spazio pubblico. Una panca e un elemento doppio si aggregano in configurazioni flessibili: la disposizione invita alla sosta senza imporre un unico modo di sedersi o di stare in gruppo.','POLIEDRO is designed to encourage interaction among young people in public space. A bench and a double element combine in flexible configurations: their arrangement invites people to stay without prescribing one way of sitting or gathering.','Abitare insieme lo spazio pubblico','Sharing public space'),
  chapter('pl-composizione','La geometria diventa uso','Geometry becomes use','La matrice esagonale costruisce una famiglia di volumi. Altezze differenti, superfici di appoggio e cavità articolano il sistema in sedute e punti di relazione. I dettagli mettono in evidenza gli spessori, le inclinazioni e gli accorgimenti per il drenaggio.','A hexagonal matrix creates a family of volumes. Different heights, supporting surfaces and cavities articulate seats and points of connection. The details show thicknesses, slopes and provisions for drainage.','La composizione esagonale','The hexagonal arrangement'),
  chapter('pl-tramonto','Una luce per prolungare la sosta','A light that extends the time together','La lampada completa l’isola sociale e introduce un centro luminoso. Il progetto accosta la massa del calcestruzzo a un corpo diffusore in policarbonato. A matter of presence porta lo stesso sistema in una dimensione espositiva, dove riflessi e penombra amplificano la percezione della materia.','The lamp completes the social island and introduces a luminous centre. The design places the mass of concrete alongside a polycarbonate diffuser. A matter of presence brings the system into an exhibition setting, where reflections and low light amplify the perception of matter.','La lampada come centro','The lamp as a centre')],
 gallery:[img('pl-seduta-1','Seduta — cavità e raccordi','Seat — cavities and connections'),img('pl-seduta-2','Seduta — geometria e drenaggio','Seat — geometry and drainage'),img('pl-schizzo','Schizzi di relazione','Sketching relationships')],
 technical:[sheet('pl-tav-15','Concept e sistema modulare','Concept and modular system','board'),sheet('pl-tav-16','Disegni tecnici e dettagli costruttivi','Technical drawings and construction details','board')]},

{id:'compluvio',name:'COMPLUVIO',discipline:'architecture',
 type:P('Architettura · Paesaggio','Architecture · Landscape'),year:'',
 cover:img('cp-cover','La serra nel paesaggio','The greenhouse in the landscape'),
 subtitle:P('La forma segue l’acqua.','Form follows water.'),
 question:P('E se fosse l’acqua a disegnare lo spazio?','What if water could shape space?'),
 lens:P('Leggere un fenomeno naturale e trasformarlo in una regola costruttiva, per uno spazio da vivere insieme.','Reading a natural phenomenon and translating it into a building principle for a shared space.'),
 intro:P('Una serra sociale e terapeutica per Cascina Linterno, Milano. Due volte vetrate si incontrano in una linea di raccolta: l’acqua piovana diventa principio generativo dello spazio.','A social and therapeutic greenhouse for Cascina Linterno, Milan. Two glazed vaults meet along a collection line: rainwater becomes the space’s organising principle.'),
 text:P('La copertura convoglia la pioggia verso un serbatoio per l’irrigazione. Il progetto esplora un ciclo di recupero dell’acqua e un rapporto continuo tra coltivazione, incontro e paesaggio. La luce attraversa la struttura e accompagna le attività all’interno.','The roof channels rain towards a reservoir for irrigation. The project explores water recovery and a continuous relationship between cultivation, gathering and landscape. Light passes through the structure, supporting the activities within.'),
 meta:[[P('Luogo','Site'),P('Cascina Linterno · Milano','Cascina Linterno · Milan')],[P('Programma','Programme'),P('Serra sociale e terapeutica','Social and therapeutic greenhouse')],[P('Principio','Principle'),P('Raccolta dell’acqua piovana','Rainwater collection')]],
 team:'Filippo Antonio Visentin',
 chapters:[
  chapter('cp-interno-2','Coltivare relazioni','Growing relationships','Il progetto per Cascina Linterno integra una serra sociale e terapeutica nel rapporto tra costruito e paesaggio. La coltivazione diventa occasione di attività condivisa, dentro un ambiente protetto ma visivamente aperto all’esterno.','The project for Cascina Linterno integrates a social and therapeutic greenhouse into the relationship between buildings and landscape. Cultivation becomes a shared activity in an environment that is sheltered yet visually open to the outside.','Coltivare insieme','Growing together'),
  chapter('cp-sezione','La sezione raccoglie','The section collects','Le due volte si incontrano in una depressione centrale che convoglia la pioggia verso la raccolta. Il sistema studiato collega serbatoio e irrigazione a bassa pressione. Il recupero dell’acqua è un obiettivo progettuale: forma della copertura e organizzazione della coltivazione sono pensate insieme.','The two vaults meet in a central valley directing rain towards collection. The proposed system connects a reservoir with low-pressure irrigation. Water recovery is a design objective: the roof form and the organisation of cultivation are considered together.','Copertura, pianta e sezione','Roof, plan and section')],
 gallery:[img('cp-interno-1','Luce e materia','Light and matter'),img('cp-volta','La volta e il prato','The vault and the meadow')],
 technical:[sheet('cp-planimetria','Inserimento a Cascina Linterno','Cascina Linterno site context','plan'),sheet('cp-copertura','Pianta delle coperture','Roof plan','plan')]},

{id:'presence',name:'A MATTER OF PRESENCE',discipline:'exhibition',
 type:P('Exhibition design · POLIEDRO','Exhibition design · POLIEDRO'),year:'2026',
 cover:img('pr-cover','Materia e riflessi','Matter and reflections'),
 subtitle:P('La materia si moltiplica nello sguardo.','Matter multiplies through perception.'),
 question:P('Quanto può cambiare un oggetto quando cambia lo spazio intorno?','How much can an object change when the surrounding space changes?'),
 lens:P('La luce e il riflesso sono materiali di progetto: cambiano la distanza, la scala e il modo in cui ci fermiamo.','Light and reflection are design materials: they change distance, scale and the way we pause.'),
 intro:P('L’allestimento di POLIEDRO traduce la presenza del materiale in un’esperienza immersiva. Specchi, penombra e un paesaggio minerale costruiscono uno spazio sospeso tra montagna e interno.','The exhibition for POLIEDRO translates material presence into an immersive experience. Mirrors, low light and a mineral landscape create a space suspended between mountain and interior.'),
 text:P('Le superfici riflettenti prolungano i moduli e frammentano i punti di vista. Al centro, una zona di sosta riunisce le persone; tende e luce controllano il rapporto con l’esterno. Il visitatore attraversa la materia prima di leggerla come oggetto.','Reflective surfaces extend the modules and fragment viewpoints. A central resting area brings people together; curtains and light control the relationship with the outside. Visitors encounter matter before reading it as an object.'),
 meta:[[P('Progetto','Project'),P('Allestimento di POLIEDRO','Exhibition for POLIEDRO')],[P('Corso','Studio'),P('Laboratorio di sintesi finale · A.A. 2025/26','Final design studio · A.Y. 2025/26')],[P('Materiali','Materials'),P('Specchi · pietra · luce','Mirrors · stone · light')]],
 team:'Filippo Antonio Visentin, Lawrence Sedra, Anna Varsavia, Nina Rosa Patanè',related:'poliedro',dark:true,
 chapters:[
  chapter('pr-paesaggio','Un paesaggio interno','An interior landscape','L’allestimento racconta POLIEDRO attraverso un’immagine minerale. La materia scura delle sedute, il terreno di pietre e la penombra costruiscono un’esperienza che richiama il paesaggio montano senza riprodurlo letteralmente.','The exhibition tells the story of POLIEDRO through a mineral landscape. Dark seating, a ground of stones and low light evoke the mountains without reproducing them literally.','Il terreno di pietre','The ground of stones'),
  chapter('pr-sedute','Moltiplicare la presenza','Multiplying presence','Gli specchi frammentano i punti di vista e moltiplicano i moduli. La zona centrale concentra la sosta e l’incontro; le tende modulano il rapporto con l’esterno. Piante e prospetti chiariscono la relazione tra percorso, quinte e area collettiva.','Mirrors fragment viewpoints and multiply modules. The central area concentrates rest and encounter; curtains mediate the outside. Plans and elevations clarify the relationship between the route, screens and collective area.','Il centro dello spazio','The centre of the space')],
 gallery:[img('pr-luce','La luce sulle sedute','Light on the seats'),img('pr-corridoio','La soglia','The threshold'),img('pr-opera','Il corridoio','The corridor'),img('pr-penombra','Penombra','Low light')],
 technical:[sheet('pr-prospetti','Pianta, sezioni e prospetti','Plan, sections and elevations','plan')]},

{id:'soundplace',name:'SOUNDPLACE',discipline:'product',
 type:P('Service design · Spazio pubblico','Service design · Public space'),year:'',
 cover:img('sp-cover','Walking Tree nel parco','Walking Tree in the park'),
 subtitle:P('Un albero, due sedute, una possibilità.','A tree, two seats, a possibility.'),
 question:P('Qual è il minimo necessario per creare un luogo di incontro?','What is the minimum needed to create a meeting place?'),
 lens:P('Un oggetto può essere anche un servizio: mi interessa ciò che accade prima, durante e dopo il suo utilizzo.','An object can also be a service: I am interested in what happens before, during and after its use.'),
 intro:P('Un luogo mobile per incontrarsi e condividere musica a Morbegno. Soundplace unisce l’idea del suono a quella del focolare: un piccolo dispositivo urbano per costruire relazioni.','A mobile place for meeting and sharing music in Morbegno. Soundplace brings together sound and the idea of a fireplace: a small urban device for building relationships.'),
 text:P('Il modulo integra un albero e un risonatore passivo per smartphone, senza alimentazione elettrica. Lo storyboard descrive un servizio ipotizzato di prenotazione, attivazione e condivisione: l’oggetto diventa parte di un’esperienza collettiva.','The module integrates a tree and a passive smartphone resonator with no electrical power supply. The storyboard describes a proposed booking, activation and sharing service: the object becomes part of a collective experience.'),
 meta:[[P('Luogo','Site'),P('Morbegno · Ponte Vanoni','Morbegno · Ponte Vanoni')],[P('Modulo','Module'),P('Walking Tree · 80 × 160 cm','Walking Tree · 80 × 160 cm')],[P('Energia','Power'),P('Risonatore passivo','Passive resonator')]],
 team:'Filippo Antonio Visentin, Francisco Junior Cuello Ramirez, Monow Sarkar',
 chapters:[
  chapter('sp-luogo','Dal bisogno al dispositivo','From a need to a device','La ricerca a Morbegno individua il bisogno di luoghi per incontrarsi e condividere musica in autonomia. Walking Tree risponde con un modulo mobile di 80 × 160 cm che integra un albero, due sedute e un risonatore passivo per smartphone.','Research in Morbegno identifies the need for places to meet and independently share music. Walking Tree responds with a mobile 80 × 160 cm module integrating a tree, two seats and a passive smartphone resonator.','Ponte Vanoni — il luogo','Ponte Vanoni — the place'),
  chapter('sp-storyboard','Progettare l’esperienza completa','Designing the complete experience','Il servizio immaginato attraversa cinque momenti: stimolo iniziale, prenotazione, attivazione, esperienza e feedback. Il telefono aiuta a trovare e attivare il modulo; la parte centrale del progetto rimane l’incontro tra persone. L’app mostrata negli schizzi è una proposta di servizio.','The proposed service spans five stages: initial trigger, booking, activation, experience and feedback. A phone helps find and activate the module; the central experience remains the encounter between people. The app shown in sketches is a service proposal.','Storyboard del servizio proposto','Proposed service storyboard')],
 gallery:[img('sp-assonometria','Walking Tree — assonometria','Walking Tree — axonometric view')],
 technical:[sheet('sp-percorso','Le cinque fasi del servizio','The five stages of the service','board')]}
];

